/**
 * Known-answer vectors for the SHA-3 competition candidates this repo implements.
 *
 * Extracted by script from sphlib's own test data, which carries the NIST SHA-3 competition KATs --
 * the message for a given length comes from the competition's fixed pseudorandom pool, and the
 * digests are the reference implementations' answers. Eighteen byte-aligned lengths per output size,
 * chosen around the block boundaries: 0, 1, 2, 3, 31, 32, 33, 55, 56, 63, 64, 65, 100, 127, 128, 129,
 * 200 and 255 bytes. Both 64 and 128 are in there deliberately -- JH pads block-aligned messages
 * differently from every other length, and nothing else would have caught it.
 *
 * Ten algorithms, so 720 vectors. The zero-length row carries more weight than it looks: ECHO, Hamsi
 * and SIMD all branch on "is the final block empty", and for those three an empty message is the only
 * fixture row that reaches that branch for every block size they use.
 */
export interface Sha3CandidateVector {
  /** The message, hex. Empty for the zero-length case. */
  readonly message: string;
  readonly digest: string;
}

